        self.chatbot_episode_cozo
            .get_or_try_init(|| async {
                let path = std::env::var("CTL_PLANE_CHATBOT_EPISODE_DB_PATH")
                    .unwrap_or_else(|_| "/var/lib/op-dbus/chatbot-episodes.db".to_string());
                anyhow::ensure!(
                    !path.is_empty() && path != ":memory:" && path != "memory",
