//! Active blob-backed gRPC reflection.
//!
//! `tonic_reflection::server::Builder` freezes its descriptor index at build
//! time. This module keeps the descriptor files indexed, but advertises service
//! names from the active plugin object blobs so discovery follows D-Bus object
//! lifetime.

use std::collections::{BTreeMap, BTreeSet, HashMap};
use std::path::PathBuf;
use std::sync::Arc;

use prost::Message;
use prost_types::{
    DescriptorProto, EnumDescriptorProto, FieldDescriptorProto, FileDescriptorProto,
    FileDescriptorSet,
};
use tokio::sync::{RwLock, mpsc};
use tokio_stream::{StreamExt, wrappers::ReceiverStream};
use tonic::{Request, Response, Status, Streaming};
use tonic_reflection::pb::v1::server_reflection_request::MessageRequest;
use tonic_reflection::pb::v1::server_reflection_response::MessageResponse;
use tonic_reflection::pb::v1::server_reflection_server::{
    ServerReflection, ServerReflectionServer,
};
use tonic_reflection::pb::v1::{
    ExtensionNumberResponse, FileDescriptorResponse, ListServiceResponse, ServerReflectionRequest,
    ServerReflectionResponse, ServiceResponse,
};

use crate::plugin_object_blob::PluginObjectBlob;

#[derive(Debug, Clone)]
pub struct ActiveReflectionCatalog {
    inner: Arc<RwLock<ActiveReflectionInner>>,
    shm_dir: PathBuf,
}

impl Default for ActiveReflectionCatalog {
    fn default() -> Self {
        Self::with_dir(crate::sealed_schema_reader::blob_catalog_dir_from_env())
    }
}

#[derive(Debug, Clone)]
struct ActiveReflectionInner {
    descriptor_sets: Vec<Vec<u8>>,
    blobs: BTreeMap<String, PluginObjectBlob>,
    index: ReflectionIndex,
    /// Last stored catalog hash, used only for change logging. Schema hashes
    /// do not cover descriptor/manifest producer revisions, so this must not
    /// suppress arrival-triggered replacement of the pinned artifacts.
    catalog_hash: Option<String>,
}

//! gRPC-Web enablement with Oracle identity metadata in the CORS
//! preflight allow-list.
//!
//! `tonic_web::enable` hard-codes its preflight `access-control-allow-headers`
//! to `x-grpc-web, content-type, x-user-agent, grpc-timeout`, and its internal
//! CORS layer is the one that actually answers browser preflights (the outer
//! transport-level `CorsLayer` never sees them). This mirrors
//! `tonic_web::enable`, adds the canonical OIA1/capability metadata headers,
//! and replaces reflected origins with the bridge's exact configured allowlist.

use std::task::{Context, Poll};
use std::time::Duration;

use tonic::body::BoxBody;
use tonic::codegen::Service;
use tonic::codegen::http::{HeaderName, Request, Response};
use tonic::server::NamedService;
use tonic_web::{GrpcWebLayer, GrpcWebService};
use tower::Layer;
use tower_http::cors::{Cors, CorsLayer};

const MAX_AGE: Duration = Duration::from_secs(86400);

const ALLOW_HEADERS: [HeaderName; 6] = [
    HeaderName::from_static("x-grpc-web"),
    HeaderName::from_static("content-type"),
    HeaderName::from_static("x-user-agent"),
    HeaderName::from_static("grpc-timeout"),
    HeaderName::from_static(crate::interceptor::ASSERTION_METADATA_KEY),
    HeaderName::from_static(crate::grpc_server::DECLARED_CAPABILITY_HEADER),
];

const EXPOSE_HEADERS: [HeaderName; 5] = [
    HeaderName::from_static("grpc-status"),
    HeaderName::from_static("grpc-message"),
    HeaderName::from_static("grpc-status-details-bin"),
    HeaderName::from_static(crate::interceptor::IDENTITY_MODE_HEADER),
    HeaderName::from_static(crate::interceptor::IDENTITY_SESSION_HEADER),
];

/// Drop-in replacement for `tonic_web::enable` with exact-origin OIA1 CORS.
pub fn enable<S>(service: S) -> GhostCorsGrpcWeb<S>
where
    S: Service<Request<BoxBody>, Response = Response<BoxBody>>,
    S: Clone + Send + 'static,
    S::Future: Send + 'static,
    S::Error: Into<Box<dyn std::error::Error + Send + Sync>> + Send,
{
    let cors = CorsLayer::new()
        .allow_origin(crate::mcp_frontend::configured_allow_origin())
        .allow_credentials(true)
        .max_age(MAX_AGE)
        .expose_headers(EXPOSE_HEADERS.to_vec())
        .allow_headers(ALLOW_HEADERS.to_vec());
…
}

